-- Seed completo da seção Comparações — MySQL/MariaDB
-- Conteúdo: 130 comparações, 1.170 eixos, 2.700 respostas de eixo, 21 fontes.
-- Gerado em 2026-08-27 a partir de comparacoes_app_seed.json.
-- O seed usa IDs estáveis e UPSERTs; pode ser executado mais de uma vez.

SET NAMES utf8mb4;
SET time_zone = "+00:00";
START TRANSACTION;

CREATE TABLE IF NOT EXISTS comparacao (
  id VARCHAR(32) NOT NULL,
  slug VARCHAR(180) NOT NULL,
  titulo VARCHAR(255) NOT NULL,
  tipo VARCHAR(40) NOT NULL,
  prioridade VARCHAR(8) NOT NULL,
  fase VARCHAR(8) NOT NULL,
  introducao MEDIUMTEXT NOT NULL,
  pergunta_central TEXT NOT NULL,
  aplicacao_pratica MEDIUMTEXT NOT NULL,
  evidencia_nivel VARCHAR(24) NOT NULL,
  evidencia_sintese MEDIUMTEXT NOT NULL,
  convergencias_json JSON NOT NULL,
  divergencias_json JSON NOT NULL,
  criticas_e_limitacoes_json JSON NOT NULL,
  questoes_para_reflexao_json JSON NOT NULL,
  fontes_principais_json JSON NOT NULL,
  nota_editorial TEXT,
  status VARCHAR(80) NOT NULL,
  data_pesquisa DATE NOT NULL,
  PRIMARY KEY (id), UNIQUE KEY uq_comparacao_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS comparacao_item (
  comparacao_id VARCHAR(32) NOT NULL,
  ordem SMALLINT UNSIGNED NOT NULL,
  tipo_entidade VARCHAR(32) NOT NULL,
  entidade_id VARCHAR(220) NOT NULL,
  entidade_nome VARCHAR(255) NOT NULL,
  papel VARCHAR(80) NULL,
  PRIMARY KEY (comparacao_id,ordem),
  KEY idx_comparacao_item_entidade (tipo_entidade,entidade_id),
  CONSTRAINT fk_item_comparacao FOREIGN KEY (comparacao_id) REFERENCES comparacao(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS comparacao_eixo (
  comparacao_id VARCHAR(32) NOT NULL,
  eixo_id CHAR(2) NOT NULL,
  ordem TINYINT UNSIGNED NOT NULL,
  titulo VARCHAR(120) NOT NULL,
  pergunta TEXT NOT NULL,
  PRIMARY KEY (comparacao_id,eixo_id),
  CONSTRAINT fk_eixo_comparacao FOREIGN KEY (comparacao_id) REFERENCES comparacao(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS comparacao_eixo_resposta (
  comparacao_id VARCHAR(32) NOT NULL,
  eixo_id CHAR(2) NOT NULL,
  entidade_id VARCHAR(220) NOT NULL,
  entidade_nome VARCHAR(255) NOT NULL,
  conteudo MEDIUMTEXT NOT NULL,
  fontes_json JSON NOT NULL,
  PRIMARY KEY (comparacao_id,eixo_id,entidade_id),
  CONSTRAINT fk_resposta_eixo FOREIGN KEY (comparacao_id,eixo_id) REFERENCES comparacao_eixo(comparacao_id,eixo_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS comparacao_evidencia_dado (
  comparacao_id VARCHAR(32) NOT NULL,
  ordem SMALLINT UNSIGNED NOT NULL,
  afirmacao TEXT NOT NULL,
  populacao_ou_contexto TEXT NOT NULL,
  desfecho TEXT NOT NULL,
  resultado TEXT NOT NULL,
  fonte_id VARCHAR(100) NOT NULL,
  PRIMARY KEY (comparacao_id,ordem),
  KEY idx_evidencia_fonte (fonte_id),
  CONSTRAINT fk_dado_comparacao FOREIGN KEY (comparacao_id) REFERENCES comparacao(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS comparacao_fonte (
  id VARCHAR(100) NOT NULL,
  tipo VARCHAR(80) NOT NULL,
  titulo VARCHAR(500) NOT NULL,
  autor VARCHAR(500) NULL,
  ano SMALLINT NULL,
  url TEXT NULL,
  escopo MEDIUMTEXT NOT NULL,
  uso_no_app TEXT NOT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Fontes de pesquisa
ON DUPLICATE KEY UPDATE tipo=VALUES(tipo),titulo=VALUES(titulo),autor=VALUES(autor),ano=VALUES(ano),url=VALUES(url),escopo=VALUES(escopo),uso_no_app=VALUES(uso_no_app);

-- Comparações principais
ON DUPLICATE KEY UPDATE slug=VALUES(slug),titulo=VALUES(titulo),tipo=VALUES(tipo),prioridade=VALUES(prioridade),fase=VALUES(fase),introducao=VALUES(introducao),pergunta_central=VALUES(pergunta_central),aplicacao_pratica=VALUES(aplicacao_pratica),evidencia_nivel=VALUES(evidencia_nivel),evidencia_sintese=VALUES(evidencia_sintese),convergencias_json=VALUES(convergencias_json),divergencias_json=VALUES(divergencias_json),criticas_e_limitacoes_json=VALUES(criticas_e_limitacoes_json),questoes_para_reflexao_json=VALUES(questoes_para_reflexao_json),fontes_principais_json=VALUES(fontes_principais_json),nota_editorial=VALUES(nota_editorial),status=VALUES(status),data_pesquisa=VALUES(data_pesquisa);

-- Entidades comparadas
ON DUPLICATE KEY UPDATE tipo_entidade=VALUES(tipo_entidade),entidade_id=VALUES(entidade_id),entidade_nome=VALUES(entidade_nome),papel=VALUES(papel);

-- Eixos de leitura
ON DUPLICATE KEY UPDATE ordem=VALUES(ordem),titulo=VALUES(titulo),pergunta=VALUES(pergunta);

-- Respostas individuais por eixo e entidade
ON DUPLICATE KEY UPDATE entidade_nome=VALUES(entidade_nome),conteudo=VALUES(conteudo),fontes_json=VALUES(fontes_json);

-- Dados verificáveis de evidência
ON DUPLICATE KEY UPDATE afirmacao=VALUES(afirmacao),populacao_ou_contexto=VALUES(populacao_ou_contexto),desfecho=VALUES(desfecho),resultado=VALUES(resultado),fonte_id=VALUES(fonte_id);

COMMIT;
